import { memo } from 'react';

const Row = memo(function Row({ item }) {
  return <li>{item.title}</li>;
});

function List({ items }) {
  return (
    <ul>
      {items.map((item) => (
        <Row key={item.id} item={item} />
      ))}
    </ul>
  );
}

